//! Parity of deterministic models and composite acquisition functions with
//! BoTorch (fixtures in `tests/fixtures/phase5d_deterministic/*.json`,
//! generated by `scripts/generate_fixtures.py --phase 5d-deterministic`):
//! openbo's multi-objective transfer acquisition function (MO-TAF), i.e.
//!
//! * `PosteriorMeanModel(ModelListGP)` of source models built like openbo's
//!   `_materialize_source_mean` (`ScaleKernel` of Matern-5/2 or RBF,
//!   `Standardize`, fixed hyperparameters): posterior means, and values and
//!   gradients of qLogEHVI (`NondominatedPartitioning`,
//!   `StochasticSampler([1])`, `tau_max=1e-3`, `fat=True`) and qEHVI for
//!   q = 1 and q = 2;
//! * the target qLogNEHVI (BoTorch's recorded base samples) and the blend
//!   `logsumexp(log w_i + term_i(X)) - log Σ w_i` of all terms
//!   ([`WeightedLogMeanExp`]) for several weight vectors;
//! * `optimize_acqf` of a blend from BoTorch's initial conditions.
//!
//! Tolerances: values 1e-9 (log values absolute below 1, relative above),
//! gradients 1e-8 (relative to the largest component, entries within 1e-14
//! count as equal); `optimize_acqf`: all but one restart reach BoTorch's
//! value within 1e-6. Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::multi_objective::{
    HypercellBounds, QExpectedHypervolumeImprovement, QExpectedHypervolumeImprovementOptions,
    QLogExpectedHypervolumeImprovement, QLogExpectedHypervolumeImprovementOptions,
    QLogNoisyExpectedHypervolumeImprovement, QLogNoisyExpectedHypervolumeImprovementOptions,
};
use botorch_core::acquisition::{AcquisitionFunction, WeightedLogMeanExp};
use botorch_core::models::PosteriorMeanModel;
use botorch_core::optim::{optimize_acqf_detailed, OptimizeAcqfOptions};
use botorch_core::{
    BatchedMultiOutputGP, BatchedMultiOutputGPOptions, KernelKind, KernelSpec, Matrix, Model,
    ModelListGP, ScaleKernelSpec, SobolQMCNormalSampler,
};
use common::{fixture_dir, matrix, matrix_rows, rel_err, Report};
use serde::Deserialize;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const GRAD_ATOL: f64 = 1e-14;
/// The seed of the samplers, different from BoTorch's (0).
const UNRECORDED_SEED: u64 = 4242;

/// A number of a fixture; the writer encodes non-finite numbers as the
/// strings "inf", "-inf" and "nan".
#[derive(Debug, Clone, Copy)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Raw {
            F(f64),
            S(String),
        }
        Ok(F(match Raw::deserialize(d)? {
            Raw::F(v) => v,
            Raw::S(s) => match s.as_str() {
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                "nan" => f64::NAN,
                other => return Err(serde::de::Error::custom(format!("not a number: {other}"))),
            },
        }))
    }
}

#[derive(Debug, Deserialize)]
struct TargetConfig {
    d: usize,
    m: usize,
    covar: String,
}

/// The target model (phase-4B format, unbatched).
#[derive(Debug, Deserialize)]
struct TargetSpec {
    config: TargetConfig,
    train_x: Vec<Vec<Vec<f64>>>,
    train_y: Vec<Vec<Vec<f64>>>,
    raw_params: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Target {
    models: Vec<TargetSpec>,
    baseline_x: Vec<Vec<f64>>,
    num_samples: usize,
    values: Vec<F>,
    grads: Vec<Vec<Vec<f64>>>,
}

/// A source sub-model built like openbo's `_materialize_source_mean`.
#[derive(Debug, Deserialize)]
struct SourceModel {
    kernel: String,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    param_names: Vec<String>,
    raw_params: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Evaluation {
    values: Vec<F>,
    grads: Vec<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct Source {
    models: Vec<SourceModel>,
    /// `2 x num_cells x m`.
    cell_bounds: Vec<Vec<Vec<F>>>,
    posterior_mean: Vec<Vec<Vec<f64>>>,
    qlogehvi_q1: Evaluation,
    qlogehvi_q2: Evaluation,
    qehvi_q1: Evaluation,
    qehvi_q2: Evaluation,
}

#[derive(Debug, Deserialize)]
struct Composite {
    weights: Vec<f64>,
    values: Vec<F>,
    grads: Vec<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct Optimize {
    weights: Vec<f64>,
    bounds: Vec<Vec<f64>>,
    initial_conditions: Vec<Vec<Vec<f64>>>,
    candidates: Vec<Vec<Vec<f64>>>,
    values: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Draw {
    d: usize,
    z: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    name: String,
    ref_point: Vec<f64>,
    tau_max: f64,
    target: Target,
    sources: Vec<Source>,
    x_q1: Vec<Vec<Vec<f64>>>,
    x_q2: Vec<Vec<Vec<f64>>>,
    composites: Vec<Composite>,
    optimize: Optimize,
    draws: Vec<Draw>,
}

fn phase_dir() -> PathBuf {
    fixture_dir().join("phase5d_deterministic")
}

fn load() -> Vec<Fixture> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(phase_dir())
        .expect("phase-5d fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(
        paths.len() >= 2,
        "phase-5d fixtures are missing; run scripts/generate_fixtures.py --phase 5d-deterministic"
    );
    paths
        .iter()
        .map(|p| {
            let text = std::fs::read_to_string(p).unwrap();
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
        })
        .collect()
}

fn vals(v: &[F]) -> Vec<f64> {
    v.iter().map(|f| f.0).collect()
}

fn flat3(v: &[Vec<Vec<f64>>]) -> Vec<f64> {
    v.iter().flatten().flatten().copied().collect()
}

fn kind(name: &str) -> KernelKind {
    match name {
        "rbf" => KernelKind::Rbf,
        "matern" => KernelKind::Matern52,
        other => panic!("unknown kernel {other}"),
    }
}

fn build_target(spec: &TargetSpec) -> Arc<dyn Model> {
    let c = &spec.config;
    let options = BatchedMultiOutputGPOptions {
        kernel: kind(&c.covar),
        ..Default::default()
    };
    let x = spec.train_x.iter().map(|b| matrix(b)).collect();
    let y = spec.train_y.iter().map(|b| matrix(b)).collect();
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!((model.dim(), model.num_outputs()), (c.d, c.m));
    model.set_raw_parameters(&spec.raw_params).unwrap();
    Arc::new(model)
}

/// `PosteriorMeanModel(ModelListGP(...))` of a source.
fn build_source(models: &[SourceModel]) -> Arc<dyn Model> {
    let members = models
        .iter()
        .map(|s| {
            let x = matrix(&s.train_x);
            let d = x.ncols();
            let options = BatchedMultiOutputGPOptions {
                covar_module: Some(
                    KernelSpec::new(kind(&s.kernel), d)
                        .with_scale_kernel(ScaleKernelSpec::new(None)),
                ),
                ..Default::default()
            };
            let mut gp =
                BatchedMultiOutputGP::new(vec![x], vec![matrix(&s.train_y)], vec![], options)
                    .unwrap();
            let names: Vec<String> = gp.parameter_names().into_iter().map(|(n, _)| n).collect();
            assert_eq!(names, s.param_names, "parameter names and order");
            gp.set_raw_parameters(&s.raw_params).unwrap();
            gp
        })
        .collect();
    let list: Arc<dyn Model> = Arc::new(ModelListGP::new(members).unwrap());
    Arc::new(PosteriorMeanModel::new(list))
}

fn cells(bounds: &[Vec<Vec<F>>]) -> HypercellBounds {
    let nc = bounds[0].len();
    let m = bounds[0][0].len();
    let flat = |b: &[Vec<F>]| b.iter().flatten().map(|f| f.0).collect::<Vec<f64>>();
    HypercellBounds::new(1, nc, m, flat(&bounds[0]), flat(&bounds[1])).unwrap()
}

/// A sampler with BoTorch's recorded base samples.
fn recorded_sampler(draws: &[Draw], num_samples: usize) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(num_samples, Some(UNRECORDED_SEED)).unwrap();
    for d in draws {
        s.set_base_samples(Matrix::from_row_slice(num_samples, d.d, &d.z))
            .unwrap();
    }
    Arc::new(s)
}

/// Values and gradients at the candidate sets `x` (and a check that the
/// batch evaluation agrees).
fn evaluate(acqf: &dyn AcquisitionFunction, x: &[Vec<Vec<f64>>]) -> (Vec<f64>, Vec<f64>) {
    let xs: Vec<Matrix> = x.iter().map(|b| matrix(b)).collect();
    let mut values = Vec::with_capacity(xs.len());
    let mut grads = Vec::new();
    for xb in &xs {
        let (v, g) = acqf.forward_with_grad(xb).unwrap();
        values.push(v);
        grads.extend(matrix_rows(&g));
    }
    let plain = acqf.forward_many(&xs).unwrap();
    for (a, b) in plain.iter().zip(&values) {
        assert!(
            (a - b).abs() <= 1e-13 * b.abs().max(1.0),
            "forward_many {a} differs from forward_with_grad {b}"
        );
    }
    (values, grads)
}

/// Error of log-space values: absolute below 1, relative above (`-inf`
/// must match).
fn log_err(a: &[f64], e: &[f64]) -> f64 {
    assert_eq!(a.len(), e.len());
    a.iter()
        .zip(e)
        .map(|(a, e)| {
            if a.is_infinite() || e.is_infinite() {
                if a == e {
                    0.0
                } else {
                    f64::INFINITY
                }
            } else {
                (a - e).abs() / e.abs().max(1.0)
            }
        })
        .fold(0.0, f64::max)
}

/// [`rel_err`] where entries within `atol` count as equal.
fn rel_err_atol(a: &[f64], e: &[f64], atol: f64) -> f64 {
    let a: Vec<f64> = a
        .iter()
        .zip(e)
        .map(|(&a, &e)| if (a - e).abs() <= atol { e } else { a })
        .collect();
    rel_err(&a, e)
}

struct Terms {
    target: Arc<dyn AcquisitionFunction>,
    sources: Vec<Arc<dyn AcquisitionFunction>>,
}

fn build_terms(f: &Fixture) -> Terms {
    let target_model = build_target(&f.target.models[0]);
    let target = QLogNoisyExpectedHypervolumeImprovement::new(
        target_model,
        &f.ref_point,
        &matrix(&f.target.baseline_x),
        QLogNoisyExpectedHypervolumeImprovementOptions {
            sampler: Some(recorded_sampler(&f.draws, f.target.num_samples)),
            ..Default::default()
        },
    )
    .unwrap();
    let sources = f
        .sources
        .iter()
        .map(|s| {
            Arc::new(
                QLogExpectedHypervolumeImprovement::from_cell_bounds(
                    build_source(&s.models),
                    &f.ref_point,
                    cells(&s.cell_bounds),
                    QLogExpectedHypervolumeImprovementOptions {
                        sampler: Some(Arc::new(
                            SobolQMCNormalSampler::new(1, Some(UNRECORDED_SEED)).unwrap(),
                        )),
                        tau_max: f.tau_max,
                        fat: true,
                        ..Default::default()
                    },
                )
                .unwrap(),
            ) as Arc<dyn AcquisitionFunction>
        })
        .collect();
    Terms {
        target: Arc::new(target),
        sources,
    }
}

#[test]
fn parity_posterior_mean_model_in_hypervolume_terms() {
    let mut r = Report::default();
    for f in load() {
        for (i, s) in f.sources.iter().enumerate() {
            let model = build_source(&s.models);
            assert!(model.is_deterministic());
            // The posterior mean (q = 2 sets, output-major per set).
            let mut mean = Vec::new();
            let mut expected = Vec::new();
            for (b, xb) in f.x_q2.iter().enumerate() {
                let p = model.posterior(&matrix(xb), false).unwrap();
                assert!(p.covariance.iter().all(|&v| v == 0.0));
                mean.extend(matrix_rows(&p.mean_matrix()));
                expected.extend(s.posterior_mean[b].iter().flatten());
            }
            let label = format!("{} source {i}", f.name);
            r.check_slices(&label, "posterior mean", &mean, &expected, VALUE_TOL);
            let cell_bounds = cells(&s.cell_bounds);
            for (q, x, log_eval, lin_eval) in [
                (1, &f.x_q1, &s.qlogehvi_q1, &s.qehvi_q1),
                (2, &f.x_q2, &s.qlogehvi_q2, &s.qehvi_q2),
            ] {
                // The base samples of a deterministic model do not matter.
                let sampler = Arc::new(SobolQMCNormalSampler::new(3, Some(7)).unwrap());
                let log = QLogExpectedHypervolumeImprovement::from_cell_bounds(
                    model.clone(),
                    &f.ref_point,
                    cell_bounds.clone(),
                    QLogExpectedHypervolumeImprovementOptions {
                        sampler: Some(sampler.clone()),
                        tau_max: f.tau_max,
                        fat: true,
                        ..Default::default()
                    },
                )
                .unwrap();
                let (v, g) = evaluate(&log, x);
                r.check(
                    &label,
                    &format!("qLogEHVI q={q} values"),
                    log_err(&v, &vals(&log_eval.values)),
                    VALUE_TOL,
                );
                r.check(
                    &label,
                    &format!("qLogEHVI q={q} gradients"),
                    rel_err_atol(&g, &flat3(&log_eval.grads), GRAD_ATOL),
                    GRAD_TOL,
                );
                let lin = QExpectedHypervolumeImprovement::from_cell_bounds(
                    model.clone(),
                    &f.ref_point,
                    cell_bounds.clone(),
                    QExpectedHypervolumeImprovementOptions {
                        sampler: Some(sampler),
                        ..Default::default()
                    },
                )
                .unwrap();
                let (v, g) = evaluate(&lin, x);
                r.check(
                    &label,
                    &format!("qEHVI q={q} values"),
                    rel_err_atol(&v, &vals(&lin_eval.values), 1e-300),
                    VALUE_TOL,
                );
                r.check(
                    &label,
                    &format!("qEHVI q={q} gradients"),
                    rel_err_atol(&g, &flat3(&lin_eval.grads), GRAD_ATOL),
                    GRAD_TOL,
                );
            }
        }
    }
    r.finish("PosteriorMeanModel in qLogEHVI / qEHVI vs BoTorch");
}

#[test]
fn parity_weighted_log_mean_exp() {
    let mut r = Report::default();
    for f in load() {
        let terms = build_terms(&f);
        let (v, g) = evaluate(terms.target.as_ref(), &f.x_q1);
        r.check(
            &f.name,
            "target qLogNEHVI values",
            log_err(&v, &vals(&f.target.values)),
            VALUE_TOL,
        );
        r.check(
            &f.name,
            "target qLogNEHVI gradients",
            rel_err_atol(&g, &flat3(&f.target.grads), GRAD_ATOL),
            GRAD_TOL,
        );
        for c in &f.composites {
            let mut all = vec![terms.target.clone()];
            all.extend(terms.sources.iter().cloned());
            let blend = WeightedLogMeanExp::new(all, c.weights.clone()).unwrap();
            let (v, g) = evaluate(&blend, &f.x_q1);
            let label = format!("{} w={:?}", f.name, c.weights);
            r.check(
                &label,
                "blend values",
                log_err(&v, &vals(&c.values)),
                VALUE_TOL,
            );
            r.check(
                &label,
                "blend gradients",
                rel_err_atol(&g, &flat3(&c.grads), GRAD_ATOL),
                GRAD_TOL,
            );
        }
    }
    r.finish("WeightedLogMeanExp (MO-TAF blend) vs BoTorch");
}

#[test]
fn parity_optimize_blend_from_identical_initial_conditions() {
    let mut r = Report::default();
    for f in load() {
        let terms = build_terms(&f);
        let mut all = vec![terms.target];
        all.extend(terms.sources);
        let blend = WeightedLogMeanExp::new(all, f.optimize.weights.clone()).unwrap();
        let options = OptimizeAcqfOptions {
            batch_initial_conditions: Some(
                f.optimize
                    .initial_conditions
                    .iter()
                    .map(|b| matrix(b))
                    .collect(),
            ),
            ..Default::default()
        };
        let k = f.optimize.values.len();
        let res =
            optimize_acqf_detailed(&blend, &matrix(&f.optimize.bounds), 1, k, 0, &options).unwrap();
        let mut agree = 0;
        let mut worst_x: f64 = 0.0;
        for (i, restart) in res.restarts.iter().enumerate() {
            let e = f.optimize.values[i];
            if (restart.acq_value - e).abs() <= 1e-6 * e.abs().max(1.0) {
                agree += 1;
                let x = matrix_rows(&restart.candidates);
                let ex: Vec<f64> = f.optimize.candidates[i].iter().flatten().copied().collect();
                let err = x
                    .iter()
                    .zip(&ex)
                    .map(|(a, b)| (a - b).abs())
                    .fold(0.0, f64::max);
                worst_x = worst_x.max(err);
            }
        }
        r.check(
            &f.name,
            "restarts below BoTorch's value",
            (k - agree) as f64,
            1.0,
        );
        r.check(&f.name, "candidates (agreeing restarts)", worst_x, 1e-6);
    }
    r.finish("optimize_acqf of the MO-TAF blend vs BoTorch");
}
